select b.id,'other','Zill Coffee Machine','Arabic-coffee machine using dedicated Zill capsules from a Kuwaiti project. The manufacturer states preparation within two minutes and 10–12 finjals per capsule. The dallah is not included.','{"catalog": {"schema_version": 1, "name_ar": "Zill — مكينة القهوة العربية", "description_ar": "جهاز لتحضير القهوة العربية بكبسولات Zill الخاصة، من مشروع كويتي. يذكر المصنع تحضير القهوة خلال دقيقتين، و١٠–١٢ فنجالًا لكل كبسولة. الدلّة غير مشمولة.", "description_en": "Arabic-coffee machine using dedicated Zill capsules from a Kuwaiti project. The manufacturer states preparation within two minutes and 10–12 finjals per capsule. The dallah is not included.", "facts": {"operation": ["تحضير آلي بكبسولات Zill الخاصة", "Automated preparation with dedicated Zill capsules"], "focus": ["القهوة العربية", "Arabic coffee"], "compatibility": ["كبسولات Zill فقط", "Zill capsules only"], "capacity": ["١٠–١٢ فنجالًا للكبسولة بحسب المصنع", "10–12 finjals per capsule according to the manufacturer"], "included": ["الدلّة غير مشمولة بالجهاز", "Dallah not included"], "programs": ["يذكر المصنع تحضيرًا خلال دقيقتين", "Manufacturer states preparation within two minutes"]}, "extra_sources": ["https://www.zillcoffee.com/pages/our-story", "https://www.zillcoffee.com/products/zill-coffee-capsules-original-flavour"], "images": [{"url": "https://cdn.shopify.com/s/files/1/0275/3537/6495/files/Blue-5.jpg?v=1705510777", "source_url": "https://www.zillcoffee.com/products/zill-blue-machine", "usage_status": "source_linked", "alt_ar": "جهاز Zill — اللون الأزرق", "alt_en": "Zill machine — Blue variant"}, {"url": "https://cdn.shopify.com/s/files/1/0275/3537/6495/files/White-5_380488e7-9337-479e-b7b2-2e7df049ae9b.jpg?v=1706460712", "source_url": "https://www.zillcoffee.com/products/zill-blue-machine", "usage_status": "source_linked", "alt_ar": "جهاز Zill — اللون الرمادي البيج", "alt_en": "Zill machine — Greige variant"}, {"url": "https://cdn.shopify.com/s/files/1/0275/3537/6495/files/Green-5_0057900e-90af-4f1c-a3e2-66df71539ec0.jpg?v=1706460712", "source_url": "https://www.zillcoffee.com/products/zill-blue-machine", "usage_status": "source_linked", "alt_ar": "جهاز Zill — اللون الأخضر الملكي", "alt_en": "Zill machine — Royal green variant"}, {"url": "https://cdn.shopify.com/s/files/1/0275/3537/6495/files/Green-6_30281b6c-6b87-45af-a1ad-ccf072a4077e.jpg?v=1706460712", "source_url": "https://www.zillcoffee.com/products/zill-blue-machine", "usage_status": "source_linked", "alt_ar": "جهاز Zill — اللون الأخضر الملكي", "alt_en": "Zill machine — Royal green variant"}, {"url": "https://cdn.shopify.com/s/files/1/0275/3537/6495/files/Blue-6.jpg?v=1706460712", "source_url": "https://www.zillcoffee.com/products/zill-blue-machine", "usage_status": "source_linked", "alt_ar": "جهاز Zill — اللون الأزرق", "alt_en": "Zill machine — Blue variant"}, {"url": "https://cdn.shopify.com/s/files/1/0275/3537/6495/files/White-3_7cc0c04e-496f-40c4-8607-e839c409c91d.jpg?v=1706460712", "source_url": "https://www.zillcoffee.com/products/zill-blue-machine", "usage_status": "source_linked", "alt_ar": "جهاز Zill — اللون الرمادي البيج", "alt_en": "Zill machine — Greige variant"}, {"url": "https://cdn.shopify.com/s/files/1/0275/3537/6495/files/Blue-3.jpg?v=1706460712", "source_url": "https://www.zillcoffee.com/products/zill-blue-machine", "usage_status": "source_linked", "alt_ar": "جهاز Zill — اللون الأزرق", "alt_en": "Zill machine — Blue variant"}, {"url": "https://cdn.shopify.com/s/files/1/0275/3537/6495/files/Green-3_ef2d1754-2039-459a-b95e-39d9657c300c.jpg?v=1706460712", "source_url": "https://www.zillcoffee.com/products/zill-blue-machine", "usage_status": "source_linked", "alt_ar": "جهاز Zill — اللون الأخضر الملكي", "alt_en": "Zill machine — Royal green variant"}]}}'::jsonb,'https://www.zillcoffee.com/products/zill-blue-machine','https://www.zillcoffee.com/products/zill-blue-machine','official_product_page','Zill Coffee','https://cdn.shopify.com/s/files/1/0275/3537/6495/files/Blue-5.jpg?v=1705510777','https://www.zillcoffee.com/products/zill-blue-machine','source_linked',array[]::text[],'2026-10-09T13:00:00Z'::timestamptz,'official',false
